import {createReplacementReview} from './replacement-review.js';
import {furnitureReplacementPorts} from './furniture-replacement.js';
import{homeBenefits,homeCapacity,homeComfort,homeUsable,homeRestable}from '../../../../src/home_model.js';
import{DOMICILE_FURNITURE as F,HOME_IMPROVEMENTS as I}from '../../../../src/home_content.js';
// Rendering existing cottage owner functions; native DOM controls remain the command/quote owner.
(()=>{
let replacement, replacementSlot='tableware';
let variant='improved',root,panel,inspected=new URL(location).searchParams.has('replacement')?'tableware':'bed',selectedStock='',last='',ready=false,pending=false;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const view=()=>window.simulationTestHooks.project('homes');
function openHome(){const s=$('#workspace_navigation select');if(s){s.value='homes';s.dispatchEvent(new Event('change',{bubbles:true}));}}
function nativeAction(id){return [...panel.querySelectorAll('[data-home-action]')].find(n=>!root.contains(n)&&n.dataset.homeAction===id);}
function run(id){const b=nativeAction(id);if(!b||b.disabled){notice(b?.parentElement?.querySelector('small')?.textContent||'This action is unavailable in the current home.');return;}b.click();last='';render();}
function notice(t){root.querySelector('[role=status]').textContent=t;}
function effects(row){const values=[];for(const[k,v]of Object.entries(row?.bonuses?.xp||{}))if(v!==1)values.push(`${k} learning ×${Number(v.toFixed(3))}`);if(row?.bonuses?.rest&&row.bonuses.rest!==1)values.push(`Rest recovery ×${Number(row.bonuses.rest.toFixed(3))}`);return values.join(' · ')||'Functional furnishing · inspect';}
function proxy(id,label){const b=nativeAction(id),reason=b?.disabled?b.parentElement.querySelector('small')?.textContent||'Currently unavailable.':!b?'Unavailable here.':'';return `<button type="button" data-fh-command="${esc(id)}" ${reason?'disabled':''}>${esc(label||b?.textContent||id)}</button>${reason?`<small>${esc(reason)}</small>`:''}`;}
function setVariant(next){variant=next;root.hidden=variant!=='improved';panel.classList.toggle('fh-candidate',variant==='improved');root.querySelector('[data-fh-baseline]')?.setAttribute('aria-pressed',String(variant==='current'));openHome();if(variant==='improved')root.scrollIntoView({block:'start'});}
function render(){if(!root||!window.simulationTestHooks.saveStatus().ownsSave)return;const v=view(),h=v.here;if(!h||h.id!=='cottage'){root.innerHTML='<p>This study is scoped to the native cottage. Use the current controls when elsewhere.</p>';return;}
const nativeNotice=[...panel.querySelectorAll('[role=status]')].find(n=>!root.contains(n))?.textContent||'';
const sleeping=!!window.simulationTestHooks.snapshot().is_sleeping;
const sig=JSON.stringify([v.state.revision,v.context.clock,v.context.money,v.context.inventory,h,inspected,selectedStock,sleeping,nativeNotice]);if(sig===last)return;last=sig;
const a=document.activeElement,focus=root.contains(a)?{cmd:a.dataset.fhCommand,inspect:a.dataset.fhInspect,select:a.hasAttribute('data-fh-stock')}:null;
const benefits=homeBenefits(v.state,v.context),comfort=homeComfort(h),used=Object.values(h.stock).reduce((a,b)=>a+b,0),cap=homeCapacity(h),usable=homeUsable(h,v.context);
const furnishings=Object.entries(h.fixtures).map(([slot,f])=>({slot,...f,def:F[JSON.parse(f.key).id],effect:benefits.rows.find(r=>r.id==='domicile.'+slot)}));
const picked=furnishings.find(f=>f.slot===inspected);if(!Object.values(F).some(f=>f.slot===inspected)&&furnishings[0])inspected=furnishings[0].slot;
const stockSelect=panel.querySelector('select[aria-label="Carried item to store"]');const options=stockSelect?[...stockSelect.options]:[];if(!options.some(o=>o.value===selectedStock))selectedStock=options[0]?.value||'';
const dep=nativeAction('deposit:'+h.id);if(stockSelect&&selectedStock&&stockSelect.value!==selectedStock){stockSelect.value=selectedStock;stockSelect.dispatchEvent(new Event('change',{bubbles:true}));}
root.innerHTML=`<div class="fh-header"><div><h2>${esc(h.name)}</h2><p class="fh-meta">${h.tenure==='owned'?'Your home':esc(h.tenure)} · ${esc(v.context.location)} · ${usable?'Services available':'Services unavailable'}</p></div><button type="button" data-fh-baseline>Compare current panel</button></div><div class="fh-summary"><span>${esc(comfort.label)} · ${comfort.score} comfort</span><span>Storage ${used} / ${cap}</span><span>${v.context.money} coins</span><span>${h.improvements.length} improvements</span></div><details class="fh-section"><summary>What this home offers</summary><p>${homeRestable(h,v.context)?'Rest is supported here. Fittings and room condition determine its current benefit.':'Rest is not currently supported by this residence and body.'}</p><p>${benefits.storageAccess?'Private residence storage is accessible here. Goods remain at this home when you travel.':'Residence services are unavailable; check your rights and body.'}</p><p>Current learning support: ${esc(Object.entries(benefits.xp).filter(([,v])=>v!==1).map(([k,v])=>`${k} ×${Number(v.toFixed(3))}`).join(', ')||'no numerical learning bonus from the present fittings')}. Practice still needs its own available activity and inputs.</p><p>Room work and repairs below use native money, materials and time. Other household services remain in More home controls.</p></details><div class="fh-grid"><div class="fh-column"><section class="fh-section"><h3>Furnishings · current effects</h3><table><thead><tr><th>Furnishing</th><th>Effect here</th><th>Inspect</th></tr></thead><tbody>${furnishings.map(f=>`<tr><td>${esc(f.def.name)}<span class="fh-owned">${f.owner==='player'?'Yours':'Provided'} · ${esc(f.slot)}</span></td><td>${f.effect?esc(effects(f.effect)):'Inactive here'}</td><td><button type="button" data-fh-inspect="${esc(f.slot)}" aria-pressed="${f.slot===inspected}">Details</button></td></tr>`).join('')}</tbody></table>${picked?`<div class="fh-inspect"><strong>${esc(picked.def.name)}</strong><p>${esc(picked.def.description)}</p><p>${esc(picked.effect?.detail||'No effect available in the current circumstances.')}</p><div class="fh-tools">${proxy('remove:'+h.id+':'+picked.slot,'Pack furnishing')}</div></div>`:''}<div data-replacement-host></div><p class="fh-meta">${esc(benefits.rows.find(r=>r.id==='domicile.comfort')?.detail||'')}</p></section><section class="fh-section"><h3>Residence storage · ${used}/${cap}</h3><div class="fh-stock"><label>Carried item <select data-fh-stock aria-label="Item to store">${options.map(o=>`<option value="${esc(o.value)}" ${o.value===selectedStock?'selected':''}>${esc(o.textContent)}</option>`).join('')}</select></label><div>${proxy('deposit:'+h.id,'Store one')}</div></div><div>${Object.entries(h.stock).map(([key,n])=>`<div class="fh-storage-row"><span>${esc(v.context.itemNames?.[key]||JSON.parse(key).id)} × ${n}</span><span>${proxy('withdraw:'+h.id+':'+key,'Take one')}</span></div>`).join('')||'<p class="fh-empty">Nothing stored here. Choose a carried item above.</p>'}</div><p class="fh-meta">Private goods at this residence. Shared chest storage remains a separate native service.</p></section></div><div class="fh-column"><section class="fh-section"><h3>Rest & preparation</h3><p class="fh-meta">${sleeping?'Sleeping.':'Not sleeping. Review your furnishings before resting.'}</p><div class="fh-state"><button type="button" data-fh-rest>${sleeping?'Stop resting':'Rest here'}</button></div><p class="fh-meta">${esc(effects({bonuses:{rest:benefits.rest}}))}. Learning effects above apply through the existing sleep system.</p></section><section class="fh-section"><h3>Repairs & rooms</h3>${Object.entries(I).map(([id,i])=>h.improvements.includes(id)?`<div class="fh-work-row"><span>${esc(i.name)}</span><span>Complete</span></div>`:`<div class="fh-work-row"><span>${esc(i.name)}<small>${i.coins} coins · ${i.wood} logs (${v.context.inventory[JSON.stringify({id:"Rough wood log"})]||0} carried) · ${i.minutes} min</small></span><span>${proxy('improve:'+id,'Do work')}</span></div>`).join('')}<p class="fh-meta">Repairs spend the shown materials, money and played time.</p></section><details class="fh-section"><summary>More home controls</summary><p>Names, tenure, household, construction and other services remain on the current panel.</p><button type="button" data-fh-baseline>Open current panel</button></details></div></div><p class="fh-notice" role="status">${esc(nativeNotice||'Select, inspect and compare without spending. Action buttons use the existing home commands.')}</p><p class="fh-foot">Functional home comparison · real native state and costs · same running life when switching.</p>`;
if(replacement){replacementSlot=inspected;root.querySelector('[data-replacement-host]')?.append(replacement.node);replacement.update();}
if(focus){const n=focus.cmd?[...root.querySelectorAll('[data-fh-command]')].find(n=>n.dataset.fhCommand===focus.cmd):focus.inspect?root.querySelector(`[data-fh-inspect="${focus.inspect}"]`):focus.select?root.querySelector('[data-fh-stock]'):null;n?.focus({preventScroll:true});}
}
function mount(){if(ready||!window.simulationTestHooks?.saveStatus().ownsSave)return;panel=$('#home_panel');if(!panel)return;ready=true;root=document.createElement('section');root.id='functional_home';root.setAttribute('aria-label','Improved functional home');panel.prepend(root);
replacement=createReplacementReview({...furnitureReplacementPorts({view,slot:()=>replacementSlot,execute:request=>{const id=request.type==='remove'?`remove:${request.home}:${request.slot}`:`install:${request.home}:${request.key}`;const b=nativeAction(id);if(!b||b.disabled)throw Error(b?.parentElement.querySelector('small')?.textContent||'Native action unavailable.');b.click();const after=view().here?.fixtures;if(request.type==='remove'?!!after?.[request.slot]:after?.[F[JSON.parse(request.key).id].slot]?.key!==request.key)throw Error('Native action did not complete. Review the current home before continuing.');last='';render();}}),escape:esc});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.fhCommand)run(b.dataset.fhCommand);else if(b?.dataset.fhInspect){inspected=b.dataset.fhInspect;last='';render();}else if(b?.hasAttribute('data-fh-baseline'))setVariant('current');else if(b?.hasAttribute('data-fh-step')){window.advanceTicks(1);render();}else if(b?.hasAttribute('data-fh-rest')){if(window.simulationTestHooks.snapshot().is_sleeping)window.end_sleeping();else{const here=[...document.querySelectorAll('[data-panel-path="local-actions"]')].find(n=>n.checkVisibility());here?.click();const sleep=$('#start_sleeping_div');if(sleep)sleep.click();else{openHome();notice('Native rest is unavailable here. Check the current panel.');return;}}openHome();last='';render();}});
root.addEventListener('change',e=>{if(e.target.hasAttribute('data-fh-stock')){selectedStock=e.target.value;last='';render();}});
const switcher=document.createElement('button');switcher.type='button';switcher.id='fh_switcher';switcher.textContent='Home comparison';switcher.onclick=()=>{setVariant('improved');};$('#workspace_pane_navigation')?.append(switcher);
new MutationObserver(records=>{if(records.every(r=>root.contains(r.target)))return;if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;render();});}}).observe(panel,{childList:true,subtree:true,characterData:true});
window.addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='mockup:command')return;const{id,command,value}=e.data;try{if(command==='variant')setVariant(value==='current'?'current':'improved');if(command==='text'){root.style.setProperty('--ui-type-body',Number(value)+'px');root.style.setProperty('--ui-type-small',Math.max(12,Number(value)-2)+'px');root.style.setProperty('--ui-type-title',(Number(value)+2)+'px');document.documentElement.style.setProperty('--ui-type-body',Number(value)+'px','important');document.documentElement.style.setProperty('--shell-context-size',Number(value)+'px','important');document.body.style.fontSize=Number(value)+'px';}if(command==='step'){window.advanceTicks(1);render();}if(command==='restore')throw Error('Use one native instance for comparison.');parent.postMessage({type:'mockup:reply',id,snapshot:{variant,route:'functional-home',save:window.simulationTestHooks.snapshot()}},location.origin);}catch(error){parent.postMessage({type:'mockup:reply',id,error:error.message},location.origin);}});
render();setVariant('improved');parent.postMessage({type:'mockup:ready'},location.origin);
}
window.addEventListener('functional-home-ready',mount);const timer=setInterval(()=>{if((!new URL(location).searchParams.has('replacement')||sessionStorage.getItem('fh-replacement-ready'))&&window.simulationTestHooks?.project('homes')?.here?.id==='cottage'){mount();clearInterval(timer);}},200);
})();
